    public enum ScrollDirection { Vertical, Horizontal }

    /// <summary>
    /// 세로/가로 스크롤 혼합 레이아웃 컨테이너.
    /// UIBaseContainer를 상속하여 UIBaseCanvas 수명주기에 통합된다.
    /// 유일한 scroll owner — ScrollRect 구독, visible range 계산, row enter/exit 전담.
    /// Section(IUIScrollSection)은 "render assignment"만 받는 passive renderer.
    /// </summary>
    [RequireComponent(typeof(ScrollRect))]
    public class UIScrollContainer : UIBaseContainer
    {
        // ────────────────────────────────────────────
        // Inspector
        // ────────────────────────────────────────────

        [Header("Direction")]
        [SerializeField] private ScrollDirection _direction = ScrollDirection.Vertical;

        [Header("Layout")]
        [SerializeField] private RectOffset _padding = new RectOffset();
        [SerializeField] private float _sectionSpacing = 10f;

        [Header("Virtualization")]
        [SerializeField] private int _bufferRows = 2;

        // ────────────────────────────────────────────
        // Scroll Position API
        // ────────────────────────────────────────────

        public bool IsInitialized => _initialized;
        public float ScrollHeight => _totalContentSize;

        public float ScrollPosition
        {
            get => GetScrollPosition();
            set => SetScrollPosition(value);
        }

        public float MaxScrollPosition
            => Mathf.Max(0f, _totalContentSize - GetViewportSize());

        // ────────────────────────────────────────────
        // UIBaseContainer Lifecycle
        // ────────────────────────────────────────────

        protected override void onAwake()
        {
            _scrollRect = GetComponent<ScrollRect>();
            _content = _scrollRect.content;
            _viewport = _scrollRect.viewport;

            NormalizeViewportRect();
            NormalizeContentRect();
        }

        protected override void onInit()
        {
            _scrollRect.onValueChanged.AddListener(OnScrollChanged);
        }

        protected override void onInitComplete()
        {
            // Frame 수집
            _frames.Clear();
            _frames.AddRange(_content.GetComponentsInChildren<UIBaseFrame>(true));

            // IUIScrollSection 수집
            CollectSections();

            // Logical row 전개 + 레이아웃
            BuildLogicalRows();
            SetContentMainAxisSize(_totalContentSize);

            // Section layout 적용
            ApplySectionLayouts();

            _initialized = true;
            UpdateVisibleRows();

            // InitComplete
            foreach (var frame in _frames)
                frame._InitComplete();
        }

        protected override void onDestroy()
        {
            if (_initialized) Clear();
        }

        // ────────────────────────────────────────────
        // Public API
        // ────────────────────────────────────────────

        public void Refresh()
        {
            if (!_initialized) return;
            for (int i = 0; i < _logicalRows.Count; i++)
            {
                if (_logicalRows[i].IsVisible)
                    _logicalRows[i].Section.RefreshRow(_logicalRows[i].LocalRowIndex);
            }
        }

        public void Rebuild()
        {
            if (!_initialized) return;

            // 모든 visible row unbind
            for (int i = 0; i < _logicalRows.Count; i++)
            {
                var row = _logicalRows[i];
                if (row.IsVisible)
                    row.Section.UnbindRow(row.LocalRowIndex);
            }

            // Section clear
            foreach (var section in _sections)
                section.ClearSection();

            _logicalRows.Clear();
            _prevFirst = -1;
            _prevLast = -1;

            // 재빌드
            CollectSections();
            BuildLogicalRows();
            SetContentMainAxisSize(_totalContentSize);
            ApplySectionLayouts();
            UpdateVisibleRows();
        }

        public void ScrollTo(UIBaseFrame frame, int localRowIndex = 0, float offset = 0f)
        {
            if (!_initialized) return;
            for (int i = 0; i < _logicalRows.Count; i++)
            {
                var row = _logicalRows[i];
                if (row.Frame == frame && row.LocalRowIndex == localRowIndex)
                {
                    ScrollPosition = row.MainAxisPosition + offset;
                    return;
                }
            }
        }

        public void Clear()
        {
            for (int i = 0; i < _logicalRows.Count; i++)
            {
                var row = _logicalRows[i];
                if (row.IsVisible)
                    row.Section.UnbindRow(row.LocalRowIndex);
            }

            foreach (var section in _sections)
                section.ClearSection();

            if (_scrollRect != null)
                _scrollRect.onValueChanged.RemoveListener(OnScrollChanged);

            _frames.Clear();
            _sections.Clear();
            _logicalRows.Clear();
            _prevFirst = -1;
            _prevLast = -1;
            _initialized = false;
            _totalContentSize = 0f;
            SetContentMainAxisSize(0f);
        }

        // ────────────────────────────────────────────
        // Internal — ScrollLogicalRow
        // ────────────────────────────────────────────

        private struct ScrollLogicalRow
        {
            public IUIScrollSection Section;
            public UIBaseFrame Frame;
            public int LocalRowIndex;
            public float MainAxisPosition;
            public float MainAxisSize;
            public bool IsVisible;
        }

        // ────────────────────────────────────────────
        // Internal State
        // ────────────────────────────────────────────

        private ScrollRect _scrollRect;
        private RectTransform _content;
        private RectTransform _viewport;
        private float _totalContentSize;
        private bool _initialized;

        private readonly List<UIBaseFrame> _frames = new List<UIBaseFrame>();
        private readonly List<IUIScrollSection> _sections = new List<IUIScrollSection>();
        private readonly List<ScrollLogicalRow> _logicalRows = new List<ScrollLogicalRow>();
        private int _prevFirst = -1;
        private int _prevLast = -1;

        // ────────────────────────────────────────────
        // Section Collection
        // ────────────────────────────────────────────

        private void CollectSections()
        {
            _sections.Clear();
            foreach (var frame in _frames)
            {
                if (frame is IUIScrollSection section)
                    _sections.Add(section);
            }
        }

        // ────────────────────────────────────────────
        // Logical Row Building
        // ────────────────────────────────────────────

        private void BuildLogicalRows()
        {
            _logicalRows.Clear();
            float pos = _padding.top;

            for (int s = 0; s < _sections.Count; s++)
            {
                var section = _sections[s];
                var frame = _frames[s]; // IUIScrollSection과 Frame은 1:1 대응
                int rowCount = section.GetLogicalRowCount();
                float rowSpacing = section.GetLogicalRowSpacing();

                for (int r = 0; r < rowCount; r++)
                {
                    float rowSize = section.GetLogicalRowMainAxisSize(r);
                    _logicalRows.Add(new ScrollLogicalRow
                    {
                        Section = section,
                        Frame = frame,
                        LocalRowIndex = r,
                        MainAxisPosition = pos,
                        MainAxisSize = rowSize,
                        IsVisible = false
                    });
                    pos += rowSize;
                    if (r < rowCount - 1) pos += rowSpacing;
                }

                if (s < _sections.Count - 1)
                    pos += _sectionSpacing;
            }

            _totalContentSize = pos + _padding.bottom;
        }

        private void ApplySectionLayouts()
        {
            float crossSize = GetCrossAxisSize();
            float pos = _padding.top;

            for (int s = 0; s < _sections.Count; s++)
            {
                var section = _sections[s];
                section.ApplySectionLayout(new UIUIScrollSectionLayout(
                    _content, _direction, pos, crossSize));

                // section 전체 높이 건너뛰기
                int rowCount = section.GetLogicalRowCount();
                float rowSpacing = section.GetLogicalRowSpacing();
                for (int r = 0; r < rowCount; r++)
                {
                    pos += section.GetLogicalRowMainAxisSize(r);
                    if (r < rowCount - 1) pos += rowSpacing;
                }

                if (s < _sections.Count - 1)
                    pos += _sectionSpacing;
            }
        }

        // ────────────────────────────────────────────
        // Virtualization (Logical Row 단위)
        // ────────────────────────────────────────────

        private void OnScrollChanged(Vector2 _) { if (_initialized) UpdateVisibleRows(); }

        private void UpdateVisibleRows()
        {
            if (_logicalRows.Count == 0) return;

            float scrollPos = GetScrollPosition();
            float vpSize = GetViewportSize();
            float crossSize = GetCrossAxisSize();

            int first = FindFirst(scrollPos);
            int last = FindLast(scrollPos, vpSize);
            first = Mathf.Max(0, first - _bufferRows);
            last = Mathf.Min(_logicalRows.Count - 1, last + _bufferRows);

            // 이탈
            if (_prevFirst >= 0)
            {
                for (int i = _prevFirst; i <= _prevLast; i++)
                {
                    if (i < first || i > last)
                    {
                        var row = _logicalRows[i];
                        if (row.IsVisible)
                        {
                            row.Section.UnbindRow(row.LocalRowIndex);
                            row.IsVisible = false;
                            _logicalRows[i] = row;
                        }
                    }
                }
            }

            // 진입
            for (int i = first; i <= last; i++)
            {
                var row = _logicalRows[i];
                if (!row.IsVisible)
                {
                    row.Section.BindRow(new UIScrollRowLayout(
                        _content, _direction,
                        row.LocalRowIndex, row.MainAxisPosition, row.MainAxisSize, crossSize));
                    row.IsVisible = true;
                    _logicalRows[i] = row;
                }
            }

            _prevFirst = first;
            _prevLast = last;
        }

        // ────────────────────────────────────────────
        // Binary Search
        // ────────────────────────────────────────────

        private int FindFirst(float scrollPos)
        {
            int lo = 0, hi = _logicalRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi) / 2;
                if (_logicalRows[mid].MainAxisPosition + _logicalRows[mid].MainAxisSize <= scrollPos)
                    lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }

        private int FindLast(float scrollPos, float vpSize)
        {
            float end = scrollPos + vpSize;
            int lo = 0, hi = _logicalRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi + 1) / 2;
                if (_logicalRows[mid].MainAxisPosition >= end) hi = mid - 1;
                else lo = mid;
            }
            return lo;
        }

        // ────────────────────────────────────────────
        // Axis Helpers
        // ────────────────────────────────────────────

        private float GetViewportSize()
            => _direction == ScrollDirection.Vertical ? _viewport.rect.height : _viewport.rect.width;

        private float GetCrossAxisSize()
            => _direction == ScrollDirection.Vertical ? _viewport.rect.width : _viewport.rect.height;

        private float GetScrollPosition()
            => _content == null ? 0f
                : (_direction == ScrollDirection.Vertical
                    ? _content.anchoredPosition.y
                    : -_content.anchoredPosition.x);

        private void SetScrollPosition(float pos)
        {
            pos = Mathf.Clamp(pos, 0f, MaxScrollPosition);
            var ap = _content.anchoredPosition;
            if (_direction == ScrollDirection.Vertical) ap.y = pos; else ap.x = -pos;
            _content.anchoredPosition = ap;
            UpdateVisibleRows();
        }

        private void SetContentMainAxisSize(float size)
        {
            if (_content == null) return;
            var sd = _content.sizeDelta;
            if (_direction == ScrollDirection.Vertical) sd.y = size; else sd.x = size;
            _content.sizeDelta = sd;
        }

        private void NormalizeViewportRect()
        {
            if (_viewport == null) return;

            _viewport.anchorMin = Vector2.zero;
            _viewport.anchorMax = Vector2.one;
            _viewport.offsetMin = Vector2.zero;
            _viewport.offsetMax = Vector2.zero;
            _viewport.pivot = new Vector2(0f, 1f);
            _viewport.anchoredPosition = Vector2.zero;
        }

        private void NormalizeContentRect()
        {
            if (_content == null) return;

            _content.anchorMin = new Vector2(0f, 1f);
            _content.anchorMax = new Vector2(1f, 1f);
            _content.pivot = new Vector2(0f, 1f);
            _content.anchoredPosition = Vector2.zero;
        }
    }
